gQv(){return"\u0626\u06d5\u0645 \u0633\u06a9\u0631\u062a\u06ce\u0631\u06d5 \u0628\u06d5\u0631\u067e\u0631\u0633\u06cc\u0627\u0631\u06d5 \u0644\u06d5 \u06a9\u0627\u0645 \u067e\u0632\u06cc\u0634\u06a9(\u06d5\u06a9\u0627\u0646). \u0647\u06d5\u0645\u0648\u0648 \u0647\u06d5\u06b5\u0645\u06d5\u0628\u0698\u06ce\u0631\u06d5 \u0628\u06c6 \u0626\u06d5\u0648\u06d5\u06cc \u0647\u06cc\u0686 \u0633\u0646\u0648\u0648\u0631\u06ce\u06a9 \u0646\u06d5\u0628\u06ce\u062a (\u0647\u06d5\u0645\u0648\u0648 \u067e\u0632\u06cc\u0634\u06a9\u06d5\u06a9\u0627\u0646 \u062f\u06d5\u0628\u06cc\u0646\u06ce\u062a)."},
gQs(){return"\u0686\u0627\u0644\u0627\u06a9\u06cc\u06cc\u06d5 \u0695\u06ce\u067e\u06ce\u062f\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646"},
gQt(){return"\u0626\u06d5\u0645 \u067e\u0632\u06cc\u0634\u06a9\u06d5 \u06a9\u0627\u0645 \u0686\u0627\u0644\u0627\u06a9\u06cc\u06cc\u06d5\u06a9\u0627\u0646 \u0626\u06d5\u0646\u062c\u0627\u0645 \u062f\u06d5\u062f\u0627\u062a. \u0647\u06d5\u0645\u0648\u0648 \u0647\u06d5\u06b5\u0645\u06d5\u0628\u0698\u06ce\u0631\u06d5 \u0628\u06c6 \u0626\u06d5\u0648\u06d5\u06cc \u0647\u06cc\u0686 \u0633\u0646\u0648\u0648\u0631\u06ce\u06a9 \u0646\u06d5\u0628\u06ce\u062a (\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u0647\u06d5\u0645\u0648\u0648 \u0634\u062a\u06ce\u06a9\u06cc \u06a9\u06d5\u062a\u0627\u0644\u06c6\u06af\u06d5\u06a9\u06d5 \u0626\u06d5\u0646\u062c\u0627\u0645 \u0628\u062f\u0627\u062a)."},
